 return <main className="studio"><header className="topbar"><div className="top-left"><button className="icon-button back-button" onClick={goToBotList} aria-label="Back to robots" title="Back to robots"><ArrowLeft size={17}/></button><img className="brand-logo small" src="/logo.png" alt=""/><div className="bot-title"><strong>{name||'Untitled bot'}</strong><span><i className="status-dot"/> Draft</span></div><span className="market-symbol" aria-label={`Market ${asset}`}>{asset}</span><ChevronDown size={13} className="muted"/></div><div className="mobile-top-tabs"><button className={tab==='code'?'active':''} onClick={requestCodeView}><Code2 size={14}/> Code</button><button className={tab==='chart'?'active':''} onClick={()=>{setTab('chart');setView('chart')}}><Activity size={14}/> Chart</button></div><div className="top-actions"><ProfileButton onClick={openProfile} label={profileLabel}/>{busy==='generate'&&<span className="generation-status" role="status"><i/> AI writing live</span>}<DateRangePicker className="backtest-dates" dates={availableDates} from={from} setFrom={setFrom} to={to} setTo={setTo}/><button className="ghost hide-small" onClick={()=>view==='code'?(setView('chart'),setTab('chart')):requestCodeView()}>{view==='code'?<><Activity size={15}/> Chart</>:<><Code2 size={15}/> Code</>}</button><button className="ghost hide-small" onClick={()=>{setOutputTab('terminal');setTerminalOpen(true);setLogs(l=>[...l,'Deploy is planned for a later phase.'])}}>Deploy <span className="coming">SOON</span></button><button className="primary backtest-button" disabled={busy==='chat'||busy==='generate'||!codeHydrated||!code.trim()||!availableDates.length||unavailableTimeframes.length>0} title={unavailableTimeframes.length?`Available ${selectedMarket?.timeframes.join(', ')}; strategy requires ${unavailableTimeframes.join(', ')}`:undefined} onClick={busy==='backtest'?()=>abortRef.current?.abort():()=>backtest()}>{busy==='generate'?<>Writing…</>:busy==='backtest'?<>Stop backtest</>:<><Play size={14} fill="currentColor"/> Backtest</>}</button></div></header>
 <div className="studio-body"><aside className={`chat-side ${chatCollapsed?'collapsed':''} ${mobilePanel==='chat'?'mobile-open':''}`}><div className="side-head"><div><span className="ai-orb"><Sparkles size={14}/></span><strong>AI partner</strong><span className={`online-dot ${aiError?'offline':'idle'}`}/></div><button className="icon-button hide-small" onClick={()=>setChatCollapsed(!chatCollapsed)}>{chatCollapsed?<PanelLeftOpen size={15}/>:<PanelLeftClose size={15}/>}</button><button className="icon-button mobile-only" onClick={()=>setMobilePanel(null)}><X size={17}/></button></div>{!chatCollapsed&&<><div className="chat-messages" ref={chatScrollRef}>{chat.length===0?<div className="chat-empty"><div className="chat-empty-icon"><MessageCircle size={19}/></div><strong>Let’s shape this strategy.</strong><p>I can help edit your rules, interpret backtest results, or fix code.</p><div className="suggestions">{['Add an RSI filter','Explain the entry logic','Make the entries more selective'].map(s=><button key={s} onClick={()=>setChatInput(s)}>{s}<ArrowRight size={12}/></button>)}</div></div>:chat.map((m,i)=><div className={`message ${m.role}`} key={i}><div className="message-avatar">{m.role==='assistant'?<Sparkles size={12}/>:<span>Y</span>}</div><div className="message-content"><ChatText content={m.content}/></div>{m.context&&<button type="button" className="chat-context-chip" onClick={()=>setContextModal(m.context!)}><Braces size={12}/>{m.context.label}</button>}{aiError&&i===chat.length-1&&m.role==='assistant'&&<button className="ai-retry-button" onClick={retryChat} disabled={!!busy}><RotateCcw size={12}/> Retry</button>}</div>)}{createError&&<button className="retry-generation" onClick={()=>void create(true)} disabled={!!busy}><RotateCcw size={12}/> Retry generation</button>}{proposal&&<div className="proposal"><div><Sparkles size={13}/> Strategy update ready</div><p className="proposal-summary">{proposalSummary}</p><button className="apply-button" onClick={applyProposal}><Check size={14}/> Apply to code editor</button><button className="text-button" onClick={()=>{setProposal('');setProposalSummary('')}}>Dismiss</button></div>}</div><div className="chat-composer"><textarea ref={chatInputRef} rows={1} value={chatInput} onChange={event=>setChatInput(event.currentTarget.value)} onKeyDown={event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();void sendChat()}}} placeholder="Message your AI partner…" aria-label="Message your AI partner"/><button className="send-button" aria-label="Send message" title="Send message" onClick={()=>void sendChat()} disabled={!chatInput.trim()||!!busy}><Send size={15}/></button></div></>}</aside><Workspace view={view} setView={setView} setTab={setTab} requestCodeView={requestCodeView} undoCode={undoCode} redoCode={redoCode} saveVersion={saveCurrentVersion} renameVersion={renameSavedVersion} deleteVersion={deleteSavedVersion} versions={versions} versionsLoading={versionsLoading} versionError={versionError} loadVersion={loadSavedVersion} cloudStatus={cloudStatus} cloudMessage={cloudMessage} code={code} setCode={setCode} editorRef={editorRef} asset={asset} from={from} setFrom={setFrom} to={to} setTo={setTo} result={result} outputTab={outputTab} setOutputTab={setOutputTab} selectedTrade={mobilePanel==='terminal'?null:selectedTrade} showTradeModal={tradeDetailsOpen} setTradeDetailsOpen={setTradeDetailsOpen} setFocusTrade={setFocusTrade} setSelectedTrade={setSelectedTrade} onAuditTrade={askAiToAuditTrade} backtest={backtest} terminalOpen={terminalOpen} setTerminalOpen={setTerminalOpen} busy={busy} logs={logs} setLogs={setLogs} setChatInput={setChatInput} setMobilePanel={setMobilePanel} chartRef={chartRef} cancelBacktest={()=>abortRef.current?.abort()} availableDates={availableDates} availabilityError={availabilityError} reloadAvailability={()=>void loadMarketAvailability()} unavailableTimeframes={unavailableTimeframes} availableTimeframes={selectedMarket?.timeframes||[]} /> </div>
 <nav className="mobile-actions"><button onClick={()=>{setChatCollapsed(false);setMobilePanel('chat')}}><MessageCircle size={17}/><span>AI chat</span>{chat.length>0&&<i/>}</button><button onClick={()=>setMobilePanel('terminal')}><Terminal size={17}/><span>Outputs</span>{logs.length>0&&<i/>}</button></nav>{mobilePanel==='terminal'&&<div className="mobile-sheet-backdrop" onClick={()=>setMobilePanel(null)}><section className="mobile-terminal-sheet" onClick={event=>event.stopPropagation()}><div className="sheet-grabber"/><OutputDock asset={asset} timeframe={result?.timeframe} from={from} to={to} logs={logs} result={result} selectedTrade={selectedTrade} showTradeModal={tradeDetailsOpen} busy={busy} active={outputTab} collapsed={false} onTabChange={setOutputTab} onCollapse={()=>setMobilePanel(null)} onClear={clearLogs} onDeleteBacktest={deleteSavedBacktest} onStop={()=>abortRef.current?.abort()} onSelectTrade={trade=>{setSelectedTrade(trade);setTradeDetailsOpen(false);setFocusTrade(trade);setView('chart');setTab('chart');setOutputTab('trades');setMobilePanel(null)}} onClearSelectedTrade={()=>{setSelectedTrade(null);setTradeDetailsOpen(false)}} onAuditTrade={askAiToAuditTrade} versions={versions} versionsLoading={versionsLoading} versionError={versionError} onLoadVersion={loadSavedVersion} onRenameVersion={renameSavedVersion} onDeleteVersion={deleteSavedVersion} compact/></section></div>}
 {codeWarning&&<CodeWarningDialog dontShow={dontShowCodeWarning} setDontShow={setDontShowCodeWarning} onCancel={()=>setCodeWarning(false)} onContinue={continueToCode}/>}<ChatContextModal context={contextModal} onClose={()=>setContextModal(null)}/><div className="keyboard-shortcut"><Command size={11}/> + ↵ <span>Backtest</span></div>
 </main>
