function CreateExtras(p:{busy:string;draftId:string;cloudStatus:string;cloudMessage:string;cloudBots:CloudBot[];availableAssets:string[];markets:AvailableMarket[];onDemo:(bot:DemoBot)=>void;onCloudBot:(bot:CloudBot)=>void;onRetry:()=>void}){const visibleDemos=demoBots.filter(bot=>{const market=p.markets.find(item=>item.asset===bot.asset);if(!market)return false;try{return parseStrategyConfig(bot.code).timeframes.every((tf:string)=>market.timeframes.includes(tf))}catch{return false}});const saved=p.cloudBots.filter(bot=>!demoBots.some(demo=>demo.id===bot.id)&&p.availableAssets.includes(bot.asset));return <>{visibleDemos.length>0&&<section className="demo-section"><div className="demo-heading"><div className="demo-heading-copy"><span>QUICK START</span><strong>Start from an example</strong></div><span className="demo-caption">{visibleDemos.length} available · based on your market history</span></div><div className="demo-grid">{visibleDemos.map(bot=><article className="demo-card" key={bot.id}><div className="demo-card-top"><span className="demo-icon"><Bot size={16}/></span><span className="demo-market">{bot.asset} · {parseStrategyConfig(bot.code).timeframes.join(' / ').toUpperCase()}</span></div><strong>{bot.name}</strong><p>{bot.description}</p><button className="demo-run" onClick={()=>p.onDemo(bot)} disabled={!!p.busy}>{p.busy==='backtest'&&p.draftId===bot.id?<><span className="spinner"/> Running…</>:<>Load &amp; backtest <ArrowRight size={14}/></>}</button></article>)}</div></section>}<div className="cloud-row"><span className={p.cloudStatus==='connected'?'data-dot':'cloud-indicator'}/><span>{p.cloudStatus==='connected'?`Cloud sync · ${p.cloudBots.length} saved robots`:p.cloudStatus==='saving'?'Saving changes…':p.cloudStatus==='connecting'?'Connecting cloud storage…':p.cloudStatus==='error'?'Cloud sync paused · drafts stay on this device':'Local draft mode'}</span>{p.cloudStatus==='error'&&<button className="text-button" onClick={p.onRetry}>Retry</button>}</div>{p.cloudMessage&&<div className="cloud-error"><strong>Cloud sync needs attention</strong><span>{readableFirebaseError(p.cloudMessage)}</span><small>Your work on this device is still available. Try again in a moment.</small></div>}{saved.length>0&&<section className="saved-bots"><div className="demo-heading"><div className="demo-heading-copy"><span>YOUR LIBRARY</span><strong>Saved robots</strong></div></div>{saved.slice(0,8).map(bot=><button className="saved-bot-row" key={bot.id} onClick={()=>p.onCloudBot(bot)}><span><strong>{bot.name}</strong><small>{bot.asset} · {bot.lastBacktest?`${bot.lastBacktest.candleCount.toLocaleString()} candles last run`:'Not backtested yet'}</small></span><ArrowRight size={14}/></button>)}</section>}</>}
function BotLibrary({bots,current,onCreate,onOpen,onOpenLocal,onRename,onDelete,onProfile,profileName,cloudStatus,cloudMessage,onRetry}:{bots:CloudBot[];current:(Partial<Draft>&{created:boolean})|null;onCreate:()=>void;onOpen:(bot:CloudBot)=>void;onOpenLocal:(draft:any)=>void;onRename:(bot:CloudBot,name:string,localOnly:boolean)=>Promise<void>;onDelete:(bot:CloudBot,localOnly:boolean)=>Promise<void>;onProfile:()=>void;profileName:string;cloudStatus:string;cloudMessage:string;onRetry:()=>void}){
 const [action,setAction]=useState<{type:'rename'|'delete';bot:CloudBot;localOnly:boolean}|null>(null);
 const [value,setValue]=useState(''),[error,setError]=useState(''),[working,setWorking]=useState(false);
 useEffect(()=>{if(!action||working)return;const onEscape=(event:KeyboardEvent)=>{if(event.key==='Escape')setAction(null)};window.addEventListener('keydown',onEscape);return()=>window.removeEventListener('keydown',onEscape)},[action,working]);
 const local=current?.created?current:null;
 const items=[...bots];
 if(local?.id&&!items.some(bot=>bot.id===local.id))items.unshift({id:local.id,name:local.name||'Untitled robot',asset:local.asset||'XAUUSD',prompt:local.prompt||'',code:local.code??starterCode,lastBacktest:null});
 const choose=(type:'rename'|'delete',bot:CloudBot,localOnly:boolean)=>{setAction({type,bot,localOnly});setValue(bot.name||'');setError('')};
 const submit=async()=>{if(!action||working)return;setWorking(true);setError('');try{if(action.type==='rename')await onRename(action.bot,value,action.localOnly);else await onDelete(action.bot,action.localOnly);setAction(null)}catch(cause){setError(cause instanceof Error?cause.message:'Could not update this robot.')}finally{setWorking(false)}};
 return <main className="bot-library"><header className="library-top"><div className="library-brand"><img className="brand-logo" src="/logo.png" alt=""/><span>Trading Vibes</span></div><div className={`library-sync ${cloudStatus==='error'?'error':''}`} title={cloudMessage||'Robot data sync status'}><i/>{cloudStatus==='saving'?'Saving robot…':cloudStatus==='connecting'?'Syncing…':cloudStatus==='error'?'Sync issue':'Cloud saved'}{cloudStatus==='error'&&<button onClick={onRetry}>Retry</button>}</div><div className="library-actions"><ProfileButton onClick={onProfile} label={profileName}/><button className="primary library-create" onClick={onCreate}><Plus size={16}/> Create a robot</button></div></header><section className="library-content"><div className="library-eyebrow"><span className="eyebrow-dot"/> STRATEGY WORKSPACE</div><div className="library-title-row"><div><h1>Your robots</h1><p>Pick up where you left off, or build a new strategy.</p></div><span className="library-count">{items.length} {items.length===1?'ROBOT':'ROBOTS'}</span></div>{items.length?<div className="robot-grid">{items.map(bot=>{const localOnly=Boolean(local?.id===bot.id&&!bots.some(saved=>saved.id===bot.id));const net=bot.lastBacktest?.metrics?.netReturn;return <article className="robot-card" key={bot.id}><div className="robot-card-top"><span className="robot-icon"><Bot size={18}/></span><span className="robot-market">{bot.asset}</span></div><button type="button" className="robot-card-open" onClick={()=>localOnly?onOpenLocal({...bot,created:true}):onOpen(bot)}><strong className="robot-name">{bot.name||'Untitled robot'}</strong><span className="robot-summary">{bot.prompt?.trim()||'No strategy description yet.'}</span></button><div className="robot-card-foot">{typeof net==='number'?<span className={net>=0?'robot-positive':'robot-negative'}>{net>=0?'+':''}{net.toFixed(2)}R <small>last result</small></span>:<span className="robot-muted">{localOnly?'Local draft':'Ready to backtest'}</span>}<div className="robot-card-actions"><button type="button" title="Rename robot" aria-label={`Rename ${bot.name}`} onClick={()=>choose('rename',bot,localOnly)}><Pencil size={15}/></button><button type="button" title="Delete robot" aria-label={`Delete ${bot.name}`} onClick={()=>choose('delete',bot,localOnly)}><Trash2 size={15}/></button></div></div></article>})}</div>:<div className="robot-empty"><span className="robot-empty-icon"><Bot size={22}/></span><strong>Your robot library is ready.</strong><p>Create your first strategy and it will appear here for quick access.</p><button className="primary" onClick={onCreate}><Plus size={15}/> Create your first robot</button></div>}</section><footer className="library-footer"><span>PRIVATE STRATEGY WORKSPACE</span><span>YOUR ROBOTS · YOUR RULES</span></footer>
 {action&&<div className="trade-modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget&&!working)setAction(null)}}><section className="trade-modal robot-action-modal" role="alertdialog" aria-modal="true" aria-labelledby="robot-action-title"><h2 id="robot-action-title">{action.type==='delete'?'Are you sure?':'Rename robot'}</h2>{action.type==='delete'?<p>Delete <strong>{action.bot.name}</strong> and its saved code, versions, chat, and backtest? This cannot be undone.</p>:<label>Robot name<input autoFocus maxLength={64} value={value} onChange={event=>setValue(event.target.value)} onKeyDown={event=>{if(event.key==='Enter')void submit()}}/></label>}{error&&<p className="robot-action-error" role="alert">{error}</p>}<div className="robot-action-buttons"><button className="ghost" disabled={working} onClick={()=>setAction(null)}>Cancel</button><button className="primary" disabled={working||(action.type==='rename'&&!value.trim())} onClick={()=>void submit()}>{working?'Working…':action.type==='delete'?'Delete robot':'Save name'}</button></div></section></div>}
 </main>;
}
function LandingPage({onStart,onSignIn,initError}:{onStart:()=>void;onSignIn:()=>void;initError:string}){
 return <main className="tv-landing"><header className="landing-nav"><a className="landing-brand" href="#top"><img src="/logo.png" alt=""/><span>TRADING VIBES</span></a><nav><a href="#platform">PLATFORM</a><a href="#process">HOW IT WORKS</a></nav><button className="landing-login" onClick={onSignIn}>LOG IN <ArrowUpRight size={14}/></button></header><section className="landing-hero" id="top"><div className="landing-hero-copy"><div className="landing-kicker"><i/> ALGORITHMIC STRATEGY STUDIO</div><h1>Build your own<br/><em>trading robots.</em></h1><p>Turn your market ideas into editable strategies. Backtest them against your historical prices and inspect every trade.</p><div className="landing-actions"><button className="landing-cta" onClick={onStart}>CREATE YOUR ROBOT <ArrowUpRight size={16}/></button><span>NO CODE REQUIRED TO GET STARTED</span></div><div className="landing-microproof"><span><i/> YOUR STRATEGY</span><span><i/> YOUR PRICE DATA</span><span><i/> YOUR RULES</span></div></div><div className="landing-visual" aria-hidden="true"><div className="landing-orbit orbit-one"/><div className="landing-orbit orbit-two"/><div className="landing-chart-grid"/><div className="landing-chart-line"><svg viewBox="0 0 540 300" preserveAspectRatio="none"><defs><linearGradient id="tv-line" x1="0" x2="1"><stop offset="0" stopColor="#f6dc76"/><stop offset="1" stopColor="#89dca7"/></linearGradient></defs><path d="M5 250 L55 226 92 239 135 175 178 191 220 146 260 165 305 95 341 120 380 66 420 91 462 38 510 54 540 18" fill="none" stroke="url(#tv-line)" strokeWidth="2.5"/><path d="M5 250 L55 226 92 239 135 175 178 191 220 146 260 165 305 95 341 120 380 66 420 91 462 38 510 54 540 18 V300 H5Z" fill="url(#tv-line)" opacity=".06"/></svg></div><span className="visual-coordinate">XAUUSD · M1<br/>PRICE SERIES</span><span className="visual-mark mark-a">ENTRY</span><span className="visual-mark mark-b">EXIT</span><div className="visual-readout"><span>STRATEGY WORKSPACE</span><strong>IDEA <i>→</i> CODE <i>→</i> REVIEW</strong></div></div><div className="landing-scroll">SCROLL TO EXPLORE <span/></div></section><section className="landing-value" id="platform"><div><span>01 / CREATE</span><strong>From an idea<br/>to a strategy.</strong><p>Describe how you read the market. Keep the generated code in your editor where you can review and refine it.</p></div><div><span>02 / BACKTEST</span><strong>Test against<br/>your history.</strong><p>Use the price data available in your account and choose the exact historical window to test.</p></div><div><span>03 / INSPECT</span><strong>See every<br/>trade clearly.</strong><p>Explore trade marks, outcomes, and price context to understand what the simulation did.</p></div></section><section className="landing-bottom" id="process"><span>TRADING VIBES · STRATEGY WORKSPACE</span><button onClick={onStart}>START BUILDING <ArrowUpRight size={14}/></button></section>{initError&&<div className="landing-setup-note" role="status">Account setup needs attention: {initError}</div>}</main>
}
function AuthPage({client:initialClient,initialMode,initError,onBack,onSuccess}:{client:CloudClient|null;initialMode:'signup'|'signin';initError:string;onBack:()=>void;onSuccess:(preserveCurrent:boolean)=>void|Promise<void>}){
 const [client,setClient]=useState(initialClient);
 const [mode,setMode]=useState(initialMode),[name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');
 const legacyGuest=(()=>{try{return client?.getProfile()?.isAnonymous===true}catch{return false}})();
 useEffect(()=>setClient(initialClient),[initialClient]);
 useEffect(()=>setMode(initialMode),[initialMode]);
 const ensureClient=async()=>{const ready=client||await connectFirebase();if(!ready)throw new Error('Account services are not configured yet. Please try again later.');setClient(ready);return ready};
 const finish=async(action:(ready:CloudClient)=>Promise<void>)=>{setBusy(true);setError('');setNotice('');try{await action(await ensureClient())}catch(reason){setError(readableFirebaseError(reason))}finally{setBusy(false)}};
 const submit=(event:FormEvent)=>{event.preventDefault();void finish(async ready=>{const preserveCurrent=mode==='signup'&&ready.getProfile()?.isAnonymous===true;if(mode==='signup')await ready.createAccount(email.trim(),password,name);else await ready.signIn(email.trim(),password);await onSuccess(preserveCurrent)})};
 const google=()=>{void finish(async ready=>{const preserveCurrent=ready.getProfile()?.isAnonymous===true;await ready.signInWithGoogle();await onSuccess(preserveCurrent)})};
 const resetPassword=()=>{if(!email.trim()){setError('Enter your email address first, then choose reset password.');return}setBusy(true);setError('');setNotice('');void ensureClient().then(ready=>ready.sendPasswordReset(email.trim())).then(()=>setNotice('Password reset email sent. Check your inbox.')).catch(reason=>setError(readableFirebaseError(reason))).finally(()=>setBusy(false))};
 return <main className="tv-auth"><header className="auth-nav"><button className="landing-brand" onClick={onBack}><img src="/logo.png" alt=""/><span>TRADING VIBES</span></button><button className="auth-back" onClick={onBack}><ArrowLeft size={14}/> BACK TO HOME</button></header><div className="auth-layout"><section className="auth-aside"><span className="landing-kicker"><i/> YOUR STRATEGY STARTS HERE</span><h1>Think it.<br/>Build it.<br/><em>Test it.</em></h1><p>A focused workspace for developing and reviewing your trading ideas.</p><span className="auth-aside-foot">PRIVATE WORKSPACE · ACCOUNT SYNC</span></section><section className="auth-card"><div className="auth-card-heading"><span>TRADING VIBES ACCOUNT</span><h2>{mode==='signup'?'Create your account':'Welcome back'}</h2><p>{mode==='signup'?'Save your strategies and return to your workspace anytime.':'Sign in to continue to your saved robots.'}</p></div>{(error||initError)&&<div className="auth-error" role="alert">{error||initError}</div>}{notice&&<div className="auth-success" role="status">{notice}</div>}{legacyGuest&&mode==='signin'&&<div className="auth-legacy-note">To keep robots from this previous guest session, create an account first. Signing in to a different account switches to its separate robot library.</div>}<button className="google-auth" type="button" onClick={google} disabled={busy}><span className="google-g">G</span> Continue with Google</button><div className="auth-divider"><span/>OR WITH EMAIL<span/></div><form onSubmit={submit} className="auth-form">{mode==='signup'&&<label>NAME<input autoComplete="name" value={name} onChange={event=>setName(event.target.value)} placeholder="Your name" maxLength={60}/></label>}<label>EMAIL<input type="email" autoComplete="email" required value={email} onChange={event=>setEmail(event.target.value)} placeholder="you@example.com"/></label><label>PASSWORD<input type="password" autoComplete={mode==='signup'?'new-password':'current-password'} minLength={6} required value={password} onChange={event=>setPassword(event.target.value)} placeholder="At least 6 characters"/></label>{mode==='signin'&&<button type="button" className="auth-forgot" onClick={resetPassword} disabled={busy}>Forgot password?</button>}<button className="auth-submit" type="submit" disabled={busy}>{busy?'PLEASE WAIT…':mode==='signup'?'CREATE ACCOUNT':'SIGN IN'} <ArrowUpRight size={15}/></button></form><p className="auth-switch">{mode==='signup'?'Already have an account?':'New to Trading Vibes?'} <button onClick={()=>{setMode(mode==='signup'?'signin':'signup');setError('');setNotice('')}}>{mode==='signup'?'Log in':'Create an account'}</button></p><small className="auth-terms">By continuing, you agree to use backtests as research tools. Simulated results are not broker execution or a promise of future performance.</small></section></div><footer className="auth-footer"><span>TRADING VIBES</span><span>IDEAS INTO TESTABLE STRATEGIES</span></footer></main>
}
function ProfileButton({onClick,label}:{onClick:()=>void;label:string}){return <button type="button" className="profile-button" onClick={onClick} aria-label="Open profile settings" title={label||'Profile settings'}><UserRound size={15}/><span>{label?label.split('@')[0]:'Profile'}</span></button>}
function ProfilePage({client,cloudStatus,cloudMessage,onBack,onRetry,onChanged,onSignOut}:{client:CloudClient|null;cloudStatus:string;cloudMessage:string;onBack:()=>void;onRetry:()=>void;onChanged:()=>void;onSignOut:()=>Promise<void>}){
 const [mode,setMode]=useState<'create'|'signin'>('create'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[displayName,setDisplayName]=useState(()=>{try{return client?.getProfile()?.displayName||''}catch{return ''}}),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');
 const profile=(()=>{try{return client?.getProfile()??null}catch{return null}})();
 const submit=async(event:FormEvent)=>{event.preventDefault();if(!client)return;setBusy(true);setError('');setNotice('');try{if(mode==='create')await client.createAccount(email.trim(),password,displayName);else await client.signIn(email.trim(),password);setPassword('');setNotice(mode==='create'?'Account secured. Your current robots are now saved to your account.':'Signed in. Your saved robots are loading.');onChanged()}catch(reason){setError(readableFirebaseError(reason))}finally{setBusy(false)}};
 const saveName=async(event:FormEvent)=>{event.preventDefault();if(!client)return;setBusy(true);setError('');setNotice('');try{await client.updateDisplayName(displayName);setNotice('Profile updated.');onChanged()}catch(reason){setError(readableFirebaseError(reason))}finally{setBusy(false)}};
 const logout=async()=>{if(!client)return;setBusy(true);setError('');try{await onSignOut()}catch(reason){setError(readableFirebaseError(reason));setBusy(false)}};
 return <main className="profile-shell"><header className="profile-top"><button className="icon-button" onClick={onBack} aria-label="Back"><ArrowLeft size={17}/></button><img className="brand-logo small" src="/logo.png" alt=""/><strong>Trading Vibes</strong><span>PROFILE SETTINGS</span></header><section className="profile-content"><div className="profile-heading"><span className="profile-avatar"><UserRound size={23}/></span><div><div className="eyebrow"><span className="eyebrow-dot"/> YOUR ACCOUNT</div><h1>Profile &amp; cloud storage</h1><p>Secure your workspace so your robots, versions, and conversations stay with your account.</p></div></div><div className="profile-status-card"><div><span className={`profile-status-dot ${cloudStatus==='connected'?'online':''}`}/><strong>{cloudStatus==='connected'?'Cloud storage connected':cloudStatus==='connecting'?'Connecting to cloud storage…':cloudStatus==='error'?'Cloud connection needs attention':'Local mode'}</strong><small>{cloudStatus==='connected'?(profile?.isAnonymous?'Guest profile · convert it to an account to keep access across browsers':'Your workspace is syncing to your account'):cloudMessage?readableFirebaseError(cloudMessage):'Sign in to keep your workspace synced across sessions.'}</small></div>{cloudStatus==='error'&&<button type="button" className="ghost" onClick={onRetry}>Retry connection</button>}</div>{error&&<div className="profile-feedback error" role="alert">{error}</div>}{notice&&<div className="profile-feedback success" role="status">{notice}</div>}{!client?<div className="profile-form-card"><h2>Cloud sync is unavailable</h2><p>{cloudMessage?readableFirebaseError(cloudMessage):'Your account connection needs attention. Please retry.'}</p><button className="primary" onClick={onRetry}>Retry connection</button></div>:profile?.isAnonymous?<div className="profile-form-card"><div className="profile-card-heading"><div><span className="profile-kicker">TEMPORARY WORKSPACE</span><h2>Save this workspace to an account</h2></div><span className="profile-secure"><ShieldAlert size={13}/> Keeps your workspace</span></div><p>Create an account to keep the robots and drafts from this session attached to your profile.</p><div className="profile-mode-tabs"><button className={mode==='create'?'active':''} onClick={()=>{setMode('create');setError('')}}>Create account</button><button className={mode==='signin'?'active':''} onClick={()=>{setMode('signin');setError('')}}>Sign in</button></div><form className="profile-form" onSubmit={submit}>{mode==='create'&&<label>DISPLAY NAME<input autoComplete="name" value={displayName} onChange={event=>setDisplayName(event.target.value)} placeholder="Your name" maxLength={60}/></label>}<label>EMAIL ADDRESS<input type="email" autoComplete="email" required value={email} onChange={event=>setEmail(event.target.value)} placeholder="you@example.com"/></label><label>PASSWORD<input type="password" autoComplete={mode==='create'?'new-password':'current-password'} minLength={6} required value={password} onChange={event=>setPassword(event.target.value)} placeholder="At least 6 characters"/></label><button className="primary profile-submit" type="submit" disabled={busy}>{busy?<><span className="spinner"/> Working…</>:mode==='create'?'Create secure account':'Sign in to existing account'}</button></form>{mode==='signin'&&<small className="profile-migration-note">Signing in opens that account’s workspace. This temporary session stays separate.</small>}</div>:<div className="profile-form-card"><div className="profile-card-heading"><div><span className="profile-kicker">ACCOUNT</span><h2>{profile?.email||'Signed in'}</h2></div><span className="profile-secure"><Check size={13}/> Account secured</span></div><p>Your robots, versions, and conversations sync to your account automatically and are available when you sign in on another device.</p><form className="profile-form" onSubmit={saveName}><label>DISPLAY NAME<input autoComplete="name" value={displayName} onChange={event=>setDisplayName(event.target.value)} placeholder="Your name" maxLength={60}/></label><button className="primary profile-submit" type="submit" disabled={busy}>{busy?'Saving…':'Save profile'}</button></form><button type="button" className="profile-signout" onClick={()=>void logout()} disabled={busy}><LogOut size={14}/> Sign out</button></div>}<div className="profile-storage-note"><strong>Cloud storage connected</strong><span>Your robots, versions, and conversations stay with your account.</span><span>Changes sync automatically as you work.</span></div></section></main>
}
function CodeWarningDialog({dontShow,setDontShow,onCancel,onContinue}:{dontShow:boolean;setDontShow:(value:boolean)=>void;onCancel:()=>void;onContinue:()=>void}){
 return <div className="trade-modal-backdrop warning-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)onCancel()}}><section className="trade-modal code-warning" role="alertdialog" aria-modal="true" aria-labelledby="code-warning-title"><span className="warning-icon"><ShieldAlert size={20}/></span><h2 id="code-warning-title">Editing the strategy can change how this robot runs</h2><p>Changes to the script affect its signals, entries, exits, and future backtest results. A code change can also make previous results no longer match the current strategy. Review your edits and run a fresh backtest before relying on them.</p><label className="warning-remember"><input type="checkbox" checked={dontShow} onChange={event=>setDontShow(event.currentTarget.checked)}/> Don’t show me this again</label><div className="warning-actions"><button className="ghost" onClick={onCancel}>Cancel</button><button className="primary" onClick={onContinue}>Continue to strategy <ArrowRight size={15}/></button></div></section></div>
}
function Workspace(p:any){
 const chooseTrade=(trade:Trade)=>{p.setSelectedTrade(trade);p.setTradeDetailsOpen(false);p.setFocusTrade(trade);p.setView('chart');p.setTab('chart');p.setOutputTab('trades');p.setTerminalOpen(true)};
 return <section className="main-column">
  <div className="workspace-head"><div className="workspace-tabs"><button className={p.view==='code'?'selected':''} onClick={p.requestCodeView}><Code2 size={14}/> Strategy.js <span className="unsaved-dot"/></button><button className={p.view==='chart'?'selected':''} onClick={()=>{p.setView('chart');p.setTab('chart')}}><Activity size={14}/> Backtest chart</button></div><div className="workspace-controls">{<div className="code-history-actions"><span className={`cloud-save-state ${p.cloudStatus==='error'?'failed':''}`} title={p.cloudMessage||'Robot code and chats sync to your private cloud account.'}><i/>{p.cloudStatus==='saving'?'Saving':p.cloudStatus==='error'?'Sync issue':p.cloudStatus==='local'?'Local only':'Saved'}</span><button className="icon-label" title="Undo" aria-label="Undo code edit" onClick={p.undoCode}><Undo2 size={15}/></button><button className="icon-label" title="Redo" aria-label="Redo code edit" onClick={p.redoCode}><Redo2 size={15}/></button><span className="history-action-divider"/><button className="icon-label save-version-action" title="Save this version" aria-label="Save this version" onClick={p.saveVersion}><Save size={15}/><span>Save version</span></button></div>}</div></div>
  {p.availabilityError&&<div className="import-notice import-error" role="alert">{p.availabilityError}<button className="text-button" onClick={p.reloadAvailability}>Retry</button></div>}
  {p.unavailableTimeframes?.length>0&&<div className="import-notice import-error" role="status">This strategy requests {p.unavailableTimeframes.join(', ')}. Available price history: {p.availableTimeframes.join(', ')||'none'}. Edit its timeframe or add matching history.</div>}
  <div className="workspace-content" style={{display:p.view==='code'?'':'none'}}><div className="editor-filebar"><span><FileCode2 size={14}/> strategy.js</span><span className="js-badge">JS</span></div><Editor height="100%" defaultLanguage="javascript" theme="vs-dark" value={p.code} onChange={(value:string|undefined)=>p.setCode(value||'')} onMount={(editor:any)=>p.editorRef.current=editor} options={{minimap:{enabled:false},fontSize:13,lineHeight:22,fontFamily:'JetBrains Mono, monospace',fontLigatures:true,automaticLayout:true,scrollBeyondLastLine:false,padding:{top:16,bottom:20},renderLineHighlight:'gutter',wordWrap:'on',tabSize:2,overviewRulerBorder:false,scrollbar:{verticalScrollbarSize:8,horizontalScrollbarSize:8},suggestOnTriggerCharacters:true}}/></div>
  <div className="chart-workspace" style={{display:p.view==='chart'?'':'none'}}>
   {p.result?<><div className="chart-stats"><div><span>NET RESULT</span><strong className={p.result.metrics.netReturn>=0?'green':'red'}>{p.result.metrics.netReturn>=0?'+':''}{fmt(p.result.metrics.netReturn)}R</strong></div><div><span>TRADES</span><strong>{p.result.metrics.trades}</strong></div><div><span>WIN RATE</span><strong>{fmt(p.result.metrics.winRate*100,1)}%</strong></div><div><span>MAX DRAWDOWN</span><strong className="red">{fmt(p.result.metrics.maxDrawdown)}R</strong></div></div><div className="chart-container" ref={p.chartRef} aria-label="Backtest price chart. Select a trade marker to inspect its audit details."/></>:<div className="chart-empty"><div className="empty-chart-icon"><Activity size={24}/></div><span className="empty-kicker">PRICE HISTORY</span><strong>Run a backtest to view your chart.</strong><p>The chart shows the stored market prices and clickable trade markers.</p><button className="quiet-action" onClick={()=>p.backtest()} disabled={p.busy==='backtest'||!p.code?.trim()||!p.availableDates.length}>Run backtest</button></div>}
  </div>
  <OutputDock asset={p.asset} timeframe={p.result?.timeframe} from={p.from} to={p.to} logs={p.logs} result={p.result} selectedTrade={p.selectedTrade} showTradeModal={p.showTradeModal} busy={p.busy} active={p.outputTab} collapsed={!p.terminalOpen} onTabChange={p.setOutputTab} onCollapse={()=>p.setTerminalOpen(!p.terminalOpen)} onClear={p.clearLogs} onDeleteBacktest={p.deleteSavedBacktest} onStop={p.cancelBacktest} onSelectTrade={chooseTrade} onClearSelectedTrade={()=>{p.setSelectedTrade(null);p.setTradeDetailsOpen(false)}} onAuditTrade={p.onAuditTrade} versions={p.versions} versionsLoading={p.versionsLoading} versionError={p.versionError} onLoadVersion={p.loadVersion} onRenameVersion={p.renameVersion} onDeleteVersion={p.deleteVersion}/>
 </section>;
}
function tradeMarkers(trades:Trade[],currentTime:number){
 const markers:any[]=[];
 for(const trade of trades){
  if(trade.entryTime>currentTime)continue;
  markers.push({id:`trade:${trade.id}:entry`,time:trade.entryTime as any,position:trade.side==='LONG'?'belowBar':'aboveBar',color:trade.side==='LONG'?'#39d6a6':'#fa7380',shape:trade.side==='LONG'?'arrowUp':'arrowDown',text:''});
  if(trade.exitTime<=currentTime)markers.push({id:`trade:${trade.id}:exit`,time:trade.exitTime as any,position:trade.side==='LONG'?'aboveBar':'belowBar',color:trade.pnl>=0?'#39d6a6':'#fa7380',shape:'circle',text:''});
 }
 return markers;
}
function ChatContextModal({context,onClose}:{context:ChatContext|null;onClose:()=>void}){
 useEffect(()=>{if(!context)return;const close=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose()};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close)},[context,onClose]);
 if(!context)return null;const data=context.data;const rows=[['Trade ID',data.tradeId],['Market / timeframe',`${data.asset} · ${data.timeframe}`],['Side',data.side],['Entry',`${data.entry} · ${data.entryTime}`],['Exit',`${data.exit} · ${data.exitTime}`],['Stop / target',`${data.stopLoss} / ${data.takeProfit}`],['Result',`${data.pnlR}R · ${data.exitReason}`]];
 return <div className="trade-modal-backdrop context-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)onClose()}}><section className="trade-modal context-modal" role="dialog" aria-modal="true" aria-labelledby="context-title"><header><div><span className="context-eyebrow">AI AUDIT CONTEXT</span><h2 id="context-title">{context.label}</h2></div><button className="icon-button" onClick={onClose} aria-label="Close context"><X size={17}/></button></header><div className="context-modal-body"><div className="context-facts">{rows.map(([label,value])=><div key={label}><span>{label}</span><strong>{String(value??'—')}</strong></div>)}</div><p className="context-limit">{data.contextLimit}</p><details><summary>Price candles · before, during and after</summary><pre>{JSON.stringify(data.contextCandles,null,2)}</pre></details><details><summary>Strategy source</summary><pre>{data.strategy}</pre></details><details><summary>Backtest metrics</summary><pre>{JSON.stringify(data.backtestMetrics,null,2)}</pre></details></div></section></div>
}
function requestsCodeChange(message:string,history:Chat[]=[]){const action='write|generate|create|edit|change|modify|update|fix|rewrite|implement|add|remove|replace|refactor|adjust|move|set|make|turn|convert|transform|build|improve';const subject='code|script|strategy|function|rules?|filters?|entries|entry|exits?|stop(?:-loss)?|targets?|risk|indicators?|logic|signal';const direct=new RegExp(`\\b(?:${action})\\b.{0,100}\\b(?:my\\s+|the\\s+|this\\s+|it\\s+into\\s+|it\\s+as\\s+|a\\s+|an\\s+)?(?:${subject})\\b|\\b(?:${subject})\\b.{0,100}\\b(?:${action})\\b`,'i').test(message);const transformation=/\b(?:turn|convert|transform)\s+(?:it|this|that)\s+into\b|\bmake\s+(?:it|this|that)\s+(?:a|an)\b/i.test(message);const strategyIdea=/\b(?:write|rewrite|create|build|make|turn|convert|transform)\b.{0,100}\b(?:liquidity|sweep|reversal|breakout|trend|scalp)\b/i.test(message);if(direct||transformation||strategyIdea)return true;const affirmative=/^\s*(?:y|yes|yeah|yep|sure|please|do it|go ahead|okay|ok)\s*[.!]?\s*$/i.test(message);const previous=history.at(-1);return Boolean(affirmative&&previous?.role==='assistant'&&/\b(?:rewrite|edit|update|change|implement|add|modify|apply)\b/i.test(previous.content))}
function hasLastDraft(){try{return Boolean(localStorage.getItem('tradefoundry:last-draft'))}catch{return false}}
function conciseAssistantText(text:string,maxLength=2400){let prose=text.replace(/```[\s\S]*?(?:```|$)/g,'');const rawCodeStart=prose.search(/^\s*(?:export\s+(?:const|function|class)|(?:async\s+)?function\s+[A-Za-z_$]|(?:const|let|var)\s+[A-Za-z_$][\w$]*\s*=|import\s+.*\s+from\s+['"])/m);if(rawCodeStart>=0)prose=prose.slice(0,rawCodeStart);const codeLine=/^\s*(?:export\s+|async\s+)?(?:const|let|var|function|return|if\s*\(|else\b|for\s*\(|while\s*\(|switch\s*\(|case\b|break;|continue;|\/\/|\/\*|\*\/|[{}]\s*[,;]?$)|=>|\b(?:stopLoss|takeProfit|timeframes|executionTimeframe)\s*:/;const clean=prose.split('\n').filter(line=>!codeLine.test(line)).join('\n').replace(/^\s*[{}[\],;]+\s*$/gm,'').replace(/\n{3,}/g,'\n\n').trim();if(clean.length<=maxLength)return clean;const head=clean.slice(0,maxLength-1);const boundary=Math.max(head.lastIndexOf('. '),head.lastIndexOf('! '),head.lastIndexOf('? '),head.lastIndexOf('\n\n'));return `${head.slice(0,boundary>maxLength*0.55?boundary+1:head.lastIndexOf(' ')).trimEnd()}…`}
function validateStrategySyntax(source:string){try{new Function(source.replace(/^\s*export\s+/gm,''))}catch(error){throw new Error(`Strategy code has a syntax error: ${error instanceof Error?error.message:'invalid JavaScript'}`)}}function err(e:unknown){return e instanceof Error?e.message:'Unknown error'}function extractCode(text:string){return extractCodeIfPresent(text)||text.slice(text.search(/export\s+const\s+config\b/)>=0?text.search(/export\s+const\s+config\b/):0).trim()}function extractCodeIfPresent(text:string){const match=text.match(/```(?:javascript|js)?\s*([\s\S]*?)```/i);if(match)return match[1].trim();const start=text.search(/export\s+const\s+config\b/);return start>=0?text.slice(start).trim():''}
export default App;
